import java.util.Scanner;

public class Main {
    static final int MAXN = 266666;
    static int n, k, M;
    static long[] factorials = new long[MAXN + 1];
    static long[] inv_factorials = new long[MAXN + 1];
    static long[][] dp_table = new long[30][22];
    static long[][] a_matrix = new long[18][1 << 17];
    static long[] b_array = new long[1 << 17];

    static long fast_pow(long base, long exp) {
        long result = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * cur) % M;
            cur = (cur * cur) % M;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        M = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(fast_pow(k, n));
            sc.close();
            return;
        }

        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (factorials[i - 1] * i) % M;
        }

        inv_factorials[n] = fast_pow(factorials[n], M - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_factorials[i] = (inv_factorials[i + 1] * (i + 1)) % M;
        }

        int half_n = n >> 1;
        for (int i = 0; i <= half_n; i++) {
            int popcnt = Integer.bitCount(i);
            a_matrix[popcnt][i] = inv_factorials[i * 2];
        }

        for (int i = 0; i < 17; i++) {
            for (int j = 0; j < 17; j++) {
                for (int u = 0; u < (1 << 17); u++) {
                    if (((u >> j) & 1) == 1) {
                        a_matrix[i][u] += a_matrix[i][u ^ (1 << j)];
                    }
                }
            }
        }

        for (int i = 0; i < 17; i++) {
            for (int u = 0; u < (1 << 17); u++) {
                a_matrix[i][u] %= M;
            }
        }

        int popcnt_half = Integer.bitCount(half_n);
        for (int i = 0; i < (1 << 17); i++) {
            for (int j = 0; j <= 17; j++) {
                for (int u = 0; u <= 17; u++) {
                    for (int v = 0; v + u <= 17; v++) {
                        dp_table[j][u + v] += a_matrix[u][i] * (j > 0 ? dp_table[j - 1][v] : 1);
                    }
                }
            }
        }

        for (int i = 0; i < (1 << 17); i++) {
            long[] dp = new long[18];
            dp[0] = 1;
            for (int j = 1; j <= k; j++) {
                long[] new_dp = new long[18];
                for (int u = 0; u <= 17; u++) {
                    for (int v = 0; v + u <= 17; v++) {
                        new_dp[u + v] += a_matrix[u][i] * dp[v];
                    }
                }
                for (int v = 0; v <= 17; v++) {
                    new_dp[v] %= M;
                }
                dp = new_dp;
            }
            b_array[i] = dp[popcnt_half];
        }

        for (int i = 0; i < 17; i++) {
            for (int j = 0; j < (1 << 17); j++) {
                if (((j >> i) & 1) == 1) {
                    b_array[j] -= b_array[j ^ (1 << i)];
                }
            }
        }

        long answer = ((fast_pow(k, n * 2) - b_array[n] * factorials[n * 2]) % M + M) % M;
        System.out.println(answer);
        sc.close();
    }
}

